/**
 * Owns Gravekeeper's existing private-state slot and received exile history writes.
 * Inputs are the original role or captured state, accepted exile fact and received day;
 * outputs retain the stored reference and original detached report result.
 * State data keeps received-day reports with their committed exile day, target and label.
 * The feedback stage owns eligibility, duplicate checks and event publication;
 * history insertion retains its original getter/spread/throw prefix with no rollback.
 * Pure payload/read data structures belong to the neutral role-state data owner;
 * this leaf retains original live references and concrete installation/commit operations.
 */
import type {
  GravekeeperReport,
  GravekeeperState,
  GravekeeperReadReport,
  GravekeeperReadState,
} from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { ExileFeedback } from "@ai-werewolf-arena/game-contract";

export function setGravekeeperState(
  roleComp: RoleComponent,
  state: GravekeeperState,
): GravekeeperReadState {
  (roleComp.privateState as { gravekeeper: GravekeeperState })["gravekeeper"] = state;
  return state;
}

export function getGravekeeperState(roleComp: RoleComponent): GravekeeperReadState | undefined {
  return (roleComp.privateState as { readonly gravekeeper?: unknown })["gravekeeper"] as
    GravekeeperReadState | undefined;
}

/** The caller retains every preflight and subsequent use/effect/publication operation. */
export function recordExileFeedback(
  state: GravekeeperReadState,
  fact: ExileFeedback,
  receivedDay: number,
): void {
  (state.history as GravekeeperReport[]).push({ ...fact, receivedDay, result: { ...fact.result } });
}

/**
 * 负责在守墓人反馈阶段记录已提交的放逐结果。输入为接受的放逐结果及当前守墓人状态；输出为报告与事件。不公开未提交目标的身份或改变放逐结算。普通历史写入在原提交位置交给本地状态所有者；校验、使用记账和发布仍在此流程。
 */
import { recordExileFeedback } from "./state";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { World } from "../../../../core/domain/world";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Role, type EntityId, type ExileFeedback } from "../../../../core/domain/model";
import { RoleCatalog } from "../catalog";
import { getDefaultRoleCatalog } from "../role-catalog-assembly";
import { resolveInspection } from "../inspection";
import { getGravekeeperState } from "./state";
import type { NightStageHandler } from "../../stages/night/contracts";

/** The manager calls this only after the voting hook confirms the main target's actual exile. */
export function captureExileFeedback(
  world: World,
  targetId: EntityId,
  exileDay: number,
  catalog: RoleCatalog = getDefaultRoleCatalog(),
): ExileFeedback | null {
  const result = resolveInspection(world, targetId, "camp", catalog);
  return result ? { exileDay, targetId, result: { ...result } } : null;
}

export const GRAVEKEEPER_FEEDBACK_STAGE: NightStageHandler = {
  id: "gravekeeper_feedback",
  priority: 550,
  async execute(ctx) {
    const fact = ctx.previousExile,
      receivedDay = ctx.currentDay();
    if (!ctx.isCurrent() || !fact || fact.exileDay !== receivedDay - 1) return;
    for (const actorId of ctx.getAliveByRole(Role.Gravekeeper)) {
      if (!ctx.isCurrent()) return;
      const role = ctx.world.getComponent(actorId, COMPONENT.Role);
      const state = role?.role === Role.Gravekeeper ? getGravekeeperState(role) : undefined;
      if (!state || state.history.some((report) => report.receivedDay === receivedDay)) continue;
      recordExileFeedback(state, fact, receivedDay);
      ctx.events.push({
        timestamp: Date.now(),
        type: "gravekeeper_reported",
        payload: { ...fact, actorId, receivedDay, result: { ...fact.result } },
      });
    }
  },
};
